2. Using cmdk
Don’t build the UI from scratch. The library cmdk (by Pace) is the gold standard. It handles the accessible dialog, filtering, and keyboard navigation.
npm install cmdk
import { Command } from 'cmdk';
import { useEffect, useState } from 'react';

export function CommandPalette() {
  const [open, setOpen] = useState(false);

  // Toggle with Cmd+K
  useEffect(() =&gt; {
    const down = (e: KeyboardEvent) =&gt; {
      if (e.key === 'k' && (e.metaKey || e.ctrlKey)) {
        e.preventDefault();
        setOpen((open) =&gt; !open);
      }
    };
    document.addEventListener('keydown', down);
    return () =&gt; document.removeEventListener('keydown', down);
  }, []);

  return (
    &lt;Command.Dialog open={open} onOpenChange={setOpen}&gt;
      &lt;Command.Input placeholder="Type a command or search..." /&gt;

      &lt;Command.List&gt;
        &lt;Command.Empty&gt;No results found.&lt;/Command.Empty&gt;

        &lt;Command.Group heading="Projects"&gt;
          &lt;Command.Item onSelect={() =&gt; console.log('Create Project')}&gt;
            Create New Project
          &lt;/Command.Item&gt;
          &lt;Command.Item onSelect={() =&gt; console.log('Search Projects')}&gt;
            Search Projects...
          &lt;/Command.Item&gt;
        &lt;/Command.Group&gt;

        &lt;Command.Group heading="Settings"&gt;
          &lt;Command.Item onSelect={() =&gt; console.log('Toggle Theme')}&gt;
            Toggle Dark Mode
          &lt;/Command.Item&gt;
        &lt;/Command.Group&gt;
      &lt;/Command.List&gt;
    &lt;/Command.Dialog&gt;
  );
}

3. Global Shortcuts
Cmd+K is just the entry point. You also want shortcuts like Cmd+S (Save) or Cmd+B (Toggle Sidebar).
Use a custom hook useKeyboardShortcut:
import { useEffect } from 'react';

function useKeyboardShortcut(key: string, callback: () =&gt; void, meta = false) {
  useEffect(() =&gt; {
    const handler = (event: KeyboardEvent) =&gt; {
      if (event.key === key && event.metaKey === meta) {
        event.preventDefault();
        callback();
      }
    };
    window.addEventListener('keydown', handler);
    return () =&gt; window.removeEventListener('keydown', handler);
  }, [key, callback, meta]);
}

// Usage
function App() {
  useKeyboardShortcut('s', () =&gt; saveProject(), true); // Cmd+S
  return &lt;div&gt;App&lt;/div&gt;;
}
By decoupling input (Keyboard/Mouse) from actions (Commands), you make your app scriptable, testable, and incredibly fast to use.

import { z } from 'zod';

export const ProjectSchema = z.object({
  id: z.string().uuid(),
  name: z.string().min(1),
  createdAt: z.string().datetime(),
  settings: z.object({
    theme: z.enum(['light', 'dark']),
    notifications: z.boolean(),
  }),
});

// Auto-derive the TypeScript type!
